    for i, (inp, out) in enumerate(demo_pairs):
        print(f"\n=== Demo Pair {i+1} ===")
        print("Input:")
        for row in inp:
            print(' '.join(str(c).rjust(2) for c in row))
        print("\nOutput:")
        for row in out:
            print(' '.join(str(c).rjust(2) for c in row))
else:
    print(f"Error: {response.status_code}")

